-- The staff guides: a library row and a training course for each. Run in the
-- Supabase SQL editor (or psql on the VPS) with the release that carries the
-- guide pages under /learning/guides. Safe to run twice: rows are inserted only
-- where the title is not there, a summary is updated only while it still reads
-- as the seed first wrote it, and questions are added only to a course that
-- has none.

-- The day end report
INSERT INTO resources (id, title, summary, kind, audience, url, published, pinned, created_by_id) SELECT 'mvofuibups1vcEkYqURe', 'The day end report', 'What the 5 PM report is, how to verify or flag it, the five figures a counsellor gives, what a branch head reads in the month view, and the admin''s consolidated report.', 'GUIDE', ARRAY['OPS_MANAGER', 'ADMIN', 'DOCUMENTATION', 'APPLICATION_TEAM_LEADER', 'FINANCE', 'PARTNER', 'COUNSELLOR', 'DESK_COUNSELLOR', 'SENIOR_COUNSELLOR', 'TRAINEE_COUNSELLOR', 'SUPER_ADMIN', 'MANAGEMENT']::text[], '/learning/guides/day-end-report', true, true, u.id FROM (SELECT id FROM users WHERE active AND role IN ('SUPER_ADMIN', 'OPS_MANAGER', 'ADMIN') ORDER BY CASE role WHEN 'SUPER_ADMIN' THEN 0 WHEN 'OPS_MANAGER' THEN 1 ELSE 2 END, created_at LIMIT 1) u WHERE NOT EXISTS (SELECT 1 FROM resources r WHERE r.title = 'The day end report');
-- The summary has not changed since it was first seeded, so there is nothing to bring up to date.
INSERT INTO training_courses (id, title, description, resource_ids, pass_mark, published, created_by_id) SELECT 'mvofuibulR1tK7l2ZMAV', 'The day end report', 'Read the guide in the learning library first. Five questions; four right is a pass.', ARRAY(SELECT r.id FROM resources r WHERE r.title = 'The day end report' ORDER BY r.created_at LIMIT 1), 80, true, NULL WHERE EXISTS (SELECT 1 FROM resources r WHERE r.title = 'The day end report') AND NOT EXISTS (SELECT 1 FROM training_courses c WHERE c.title = 'The day end report');
INSERT INTO training_questions (id, course_id, prompt, options, correct_index, sort_order)
SELECT v.id, c.id, v.prompt, v.options, v.correct_index, v.sort_order
FROM training_courses c
JOIN (VALUES ('mvofuibuLGW45OJ0ERwv', 'At what time, India time, is the day end report issued unless Platform settings say otherwise?', ARRAY['9 AM', '1 PM', '5 PM', 'Midnight']::text[], 2, 10), ('mvofuibuc8kQgInQjKK1', 'Which of these is NOT one of the five figures a counsellor gives?', ARRAY['Leads received', 'Connected calls', 'Registrations done', 'Emails sent']::text[], 3, 20), ('mvofuibum0uSld17vukS', 'What happens to a report that is not answered by the cutoff?', ARRAY['It is recorded as Missed', 'It is verified for you', 'It is deleted', 'It stays open until the next day']::text[], 0, 30), ('mvofuibuVg58kVDVRcf6', 'What should a counsellor do when a box in the day''s figures has nothing to report?', ARRAY['Leave it blank', 'Type 0', 'Type a dash', 'Flag the report']::text[], 1, 40), ('mvofuibudVxtOxLdbx8P', 'Which screen does a branch head open to read their own branch''s figures for a month?', ARRAY['Day end figures', 'Day end reports', 'Platform settings', 'Targets']::text[], 0, 50)) AS v(id, prompt, options, correct_index, sort_order) ON true
WHERE c.title = 'The day end report' AND NOT EXISTS (SELECT 1 FROM training_questions x WHERE x.course_id = c.id);

-- The Ausbildung process in the portal
INSERT INTO resources (id, title, summary, kind, audience, url, published, pinned, created_by_id) SELECT 'mvofuibu7iCX2-hFJgiY', 'The Ausbildung process in the portal', 'The written process''s 19 steps and six desks as the portal records them: the hand-over, the mentor, the statuses per desk, the documents per stage, the payment milestones, the turnaround follow-up and what the student sees.', 'GUIDE', ARRAY['PARTNER', 'COUNSELLOR', 'SENIOR_COUNSELLOR', 'TRAINEE_COUNSELLOR', 'DESK_COUNSELLOR', 'DOCUMENTATION', 'APPLICATION_TEAM_LEADER', 'ADMIN', 'OPS_MANAGER', 'SUPER_ADMIN']::text[], '/learning/guides/ausbildung-process', true, true, u.id FROM (SELECT id FROM users WHERE active AND role IN ('SUPER_ADMIN', 'OPS_MANAGER', 'ADMIN') ORDER BY CASE role WHEN 'SUPER_ADMIN' THEN 0 WHEN 'OPS_MANAGER' THEN 1 ELSE 2 END, created_at LIMIT 1) u WHERE NOT EXISTS (SELECT 1 FROM resources r WHERE r.title = 'The Ausbildung process in the portal');
-- The summary has not changed since it was first seeded, so there is nothing to bring up to date.
INSERT INTO training_courses (id, title, description, resource_ids, pass_mark, published, created_by_id) SELECT 'mvofuibuE4kKUVC6uvwC', 'The Ausbildung process in the portal', 'Read the guide in the learning library first. Five questions; four right is a pass.', ARRAY(SELECT r.id FROM resources r WHERE r.title = 'The Ausbildung process in the portal' ORDER BY r.created_at LIMIT 1), 80, true, NULL WHERE EXISTS (SELECT 1 FROM resources r WHERE r.title = 'The Ausbildung process in the portal') AND NOT EXISTS (SELECT 1 FROM training_courses c WHERE c.title = 'The Ausbildung process in the portal');
INSERT INTO training_questions (id, course_id, prompt, options, correct_index, sort_order)
SELECT v.id, c.id, v.prompt, v.options, v.correct_index, v.sort_order
FROM training_courses c
JOIN (VALUES ('mvofuibuAqP2DmAIAsLA', 'Which button does the branch press to hand an Ausbildung file to the documentation desk?', ARRAY['Hand to the documentation desk', 'Update status', 'Set the mentor', 'Save Ausbildung details']::text[], 0, 10), ('mvofuibu_bWn6RcWX1aP', 'Who names the documentation mentor, and where?', ARRAY['The counsellor, on the Profile tab', 'The documentation desk, under Mentor on the Ausbildung tab', 'The student, in the portal', 'The placement team, on the tracker']::text[], 1, 20), ('mvofuibu864okJfI-LVc', 'Which of these does the portal NOT do?', ARRAY['Raise a follow-up task when a step is over its turnaround', 'Tell the counsellor the mentor''s name', 'Send the hand-over emails', 'Light the desk a file is with']::text[], 2, 30), ('mvofuibukiBKgICPUV2n', 'How often is a turnaround follow-up task raised for one file at one step?', ARRAY['Every day until the status moves', 'Once per stay in the step', 'Once a week', 'Never; only the tracker shows it']::text[], 1, 40), ('mvofuibu0CCM0qVO9dDA', 'What status does a new Ausbildung application start at?', ARRAY['Mentor assigned', 'Document collection by the counsellor', 'German A2 / B1 pending', 'Employer matching']::text[], 2, 50)) AS v(id, prompt, options, correct_index, sort_order) ON true
WHERE c.title = 'The Ausbildung process in the portal' AND NOT EXISTS (SELECT 1 FROM training_questions x WHERE x.course_id = c.id);

-- What is there now.
SELECT 'Guides in the library ' || count(*) FROM resources WHERE title IN ('The day end report', 'The Ausbildung process in the portal')
UNION ALL SELECT 'Guide courses ' || count(*) FROM training_courses WHERE title IN ('The day end report', 'The Ausbildung process in the portal')
UNION ALL SELECT 'Guide questions ' || count(*) FROM training_questions WHERE course_id IN (SELECT id FROM training_courses WHERE title IN ('The day end report', 'The Ausbildung process in the portal'));

